export declare const knowledgeBaseTheme = "/* \u77E5\u8BC6\u5E93\u98CE\u683C */\n#wemd {\n    padding: 5px 24px;\n    max-width: 677px;\n    margin: 0 auto;\n    /* \u4F7F\u7528\u7CFB\u7EDF\u65E0\u886C\u7EBF\u5B57\u4F53\uFF0C\u4FDD\u6301\u5E72\u51C0\u5229\u843D */\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Helvetica Neue\", \"PingFang SC\", sans-serif;\n    color: #37352F;\n    /* \u7ECF\u5178\u7684\u7B14\u8BB0\u6DF1\u7070\u8272 */\n    background-color: transparent;\n    /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n    word-break: break-word;\n}\n\n/* \u6BB5\u843D - \u7D27\u51D1\u4F46\u8212\u9002 */\n#wemd p {\n    margin-top: 16px;\n    margin-bottom: 16px;\n    line-height: 1.75;\n    letter-spacing: 0.2px;\n    text-align: justify;\n    color: #37352F;\n    font-size: 16px;\n}\n\n/* \n * \u4E00\u7EA7\u6807\u9898 - \u9875\u9762\u6807\u9898\u611F\n * \u5C31\u50CF\u7B14\u8BB0\u9875\u9762\u7684\u6700\u9876\u7AEF\u6807\u9898\n */\n#wemd h1 {\n    margin-top: 50px;\n    margin-bottom: 40px;\n    text-align: left;\n    border-bottom: 1px solid #E3E2E0;\n    /* \u6781\u7EC6\u7684\u5206\u5272\u7EBF */\n    padding-bottom: 20px;\n}\n\n#wemd h1 .content {\n    font-size: 28px;\n    font-weight: 700;\n    color: #37352F;\n    display: inline-block;\n    line-height: 1.2;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* \n * \u4E8C\u7EA7\u6807\u9898 - \u533A\u5757\u5206\u5272\n * \u5E26\u6709\u6D45\u7070\u8272\u80CC\u666F\u6761\uFF0C\u7C7B\u4F3C Notion \u7684 H1 block\n */\n#wemd h2 {\n    margin-top: 40px;\n    margin-bottom: 20px;\n    text-align: left;\n}\n\n#wemd h2 .content {\n    display: block;\n    /* \u5360\u6EE1\u6574\u884C */\n    font-size: 22px;\n    font-weight: 600;\n    color: #37352F;\n    padding: 8px 12px;\n    background-color: #F7F6F3;\n    /* \u7ECF\u5178\u7684\u6D45\u7070\u5E95\u8272 */\n    border-radius: 4px;\n    line-height: 1.3;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* \n * \u4E09\u7EA7\u6807\u9898 - \u91CD\u70B9\u6807\u8BB0\n * \u50CF\u662F\u7ED9\u6587\u5B57\u52A0\u4E86\u989C\u8272\u6807\u8BB0\n */\n#wemd h3 {\n    margin-top: 30px;\n    margin-bottom: 12px;\n}\n\n#wemd h3 .content {\n    font-size: 18px;\n    font-weight: 600;\n    color: #37352F;\n    display: inline-block;\n    /* \u5E95\u90E8\u5C40\u90E8\u9AD8\u4EAE */\n    border-bottom: 3px solid #FDECC8;\n    /* \u5976\u9EC4\u8272 */\n    padding-bottom: 2px;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* \u56DB\u7EA7\u6807\u9898 - \u5C0F\u8282 */\n#wemd h4 {\n    margin-top: 24px;\n    margin-bottom: 8px;\n    text-align: left;\n}\n\n#wemd h4 .content {\n    display: inline-block;\n    font-size: 16px;\n    font-weight: 600;\n    color: #EB5757;\n    /* \u9192\u76EE\u7684\u7EA2\u8272\uFF0C\u7528\u4E8E\u8B66\u793A\u6216\u5F3A\u8C03 */\n    line-height: 1.4;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* \n * \u5217\u8868 - \u7ED3\u6784\u5316\u7F29\u8FDB\n */\n#wemd ul {\n    list-style-type: disc;\n    padding-left: 24px;\n    margin: 16px 0;\n    color: #37352F;\n}\n\n#wemd ul li {\n    margin-bottom: 8px;\n    line-height: 1.7;\n}\n\n#wemd li section {\n    color: #37352F;\n    font-size: 16px;\n}\n\n/* \u6709\u5E8F\u5217\u8868 */\n#wemd ol {\n    list-style-type: decimal;\n    padding-left: 24px;\n    margin: 16px 0;\n    color: #37352F;\n    font-weight: 600;\n}\n\n#wemd ul ul {\n    list-style-type: circle;\n    margin-top: 6px;\n}\n\n#wemd ol ol {\n    list-style-type: lower-alpha;\n}\n\n#wemd ol li {\n    margin-bottom: 8px;\n    line-height: 1.7;\n}\n\n#wemd ol li section {\n    color: #37352F;\n    font-weight: normal;\n    font-size: 16px;\n}\n\n/* \n * \u5F15\u7528 - Callout \u63D0\u793A\u6846\u98CE\u683C\n * \u8FD9\u662F\u8FD9\u6B3E\u4E3B\u9898\u7684\u7075\u9B42\n */\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n    margin: 24px 0;\n    padding: 16px 16px 16px 20px;\n    background-color: #F1F1EF;\n    /* \u9ED8\u8BA4\u6D45\u7070\u80CC\u666F */\n    border: none;\n    /* \u65E0\u8FB9\u6846 */\n    border-radius: 4px;\n    border-left: 4px solid #37352F;\n    /* \u5DE6\u4FA7\u6DF1\u8272\u5F3A\u63D0\u793A */\n    overflow: visible !important;\n}\n\n/* \u9488\u5BF9\u4E0D\u540C\u5C42\u7EA7\u5F15\u7528\uFF0C\u7ED9\u4E88\u4E0D\u540C\u989C\u8272\uFF0C\u6A21\u62DF Info/Warning */\n#wemd .multiquote-2 {\n    background-color: #E7F3F8;\n    /* \u6D45\u84DD\u80CC\u666F (Info) */\n    border-left-color: #2D9CDB;\n}\n\n#wemd .multiquote-3 {\n    background-color: #FDF5F2;\n    /* \u6D45\u6A59\u80CC\u666F (Warning) */\n    border-left-color: #F2994A;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n    margin: 0;\n    color: #37352F;\n    font-size: 15px;\n    line-height: 1.6;\n}\n\n/* \u94FE\u63A5 - \u7B80\u6D01\u4E0B\u5212\u7EBF */\n#wemd a {\n    color: #37352F;\n    text-decoration: none;\n    border-bottom: 1px solid #999;\n    /* \u7070\u8272\u4E0B\u5212\u7EBF */\n    font-weight: 500;\n    transition: border-color 0.2s;\n}\n\n/* \n * \u52A0\u7C97 - \u9EC4\u8272\u9AD8\u5149\u7B14\n * \u5B8C\u5168\u590D\u523B Notion \u7684 Highlight \u6548\u679C\n */\n#wemd strong {\n    color: #37352F;\n    font-weight: 600;\n    background-color: #FDECC8;\n    /* \u9AD8\u4EAE\u9EC4 */\n    padding: 2px 4px;\n    margin: 0 2px;\n    border-radius: 3px;\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n    color: #37352F;\n    font-style: italic;\n    opacity: 0.7;\n}\n\n#wemd em strong {\n    color: #37352F;\n    opacity: 1;\n}\n\n/* \u9AD8\u4EAE - \u9EC4\u8272\u6807\u8BB0 */\n#wemd mark {\n    background: #FDECC8;\n    color: #37352F;\n    padding: 2px 4px;\n    border-radius: 3px;\n}\n\n/* \u5220\u9664\u7EBF */\n#wemd del {\n    text-decoration: line-through;\n    color: #999;\n}\n\n/* \u5206\u9694\u7EBF */\n#wemd hr {\n    margin: 40px auto;\n    border: 0;\n    height: 1px;\n    background-color: #E3E2E0;\n    /* \u6781\u6D45\u7070 */\n    width: 100%;\n}\n\n/* \u56FE\u7247 - \u5E72\u51C0\u65E0\u9634\u5F71 */\n#wemd img {\n    display: block;\n    margin: 30px auto;\n    width: 100%;\n    border-radius: 4px;\n    box-shadow: none;\n    /* \u7B14\u8BB0\u98CE\u683C\u901A\u5E38\u4E0D\u9700\u8981\u9634\u5F71 */\n    border: 1px solid #E3E2E0;\n    /* \u53EA\u6709\u4E00\u5708\u7EC6\u7EBF */\n}\n\n#wemd figcaption {\n    margin-top: 8px;\n    text-align: center;\n    color: #999;\n    font-size: 14px;\n}\n\n/* \n * \u884C\u5185\u4EE3\u7801 - \u7ECF\u5178\u7684\u7EA2\u5B57\u7070\u5E95\n */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n    color: #EB5757;\n    /* \u7EA2\u8272\u6587\u5B57 */\n    background: rgba(135, 131, 120, 0.15);\n    /* \u534A\u900F\u660E\u7070\u5E95 */\n    border: none;\n    padding: 3px 6px;\n    margin: 0 4px;\n    border-radius: 4px;\n    font-size: 14px;\n    font-family: \"SFMono-Regular\", Consolas, \"Liberation Mono\", Menlo, monospace;\n}\n\n/* \u4EE3\u7801\u5757 - \u6781\u7B80\u7070 */\n/* \u4EE3\u7801\u5757 - \u6CE8\u610F\uFF1A\u4E0D\u8981\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272 */\n#wemd pre code.hljs {\n    display: block;\n    padding: 20px;\n    background: #F7F6F3;\n    /* color \u7531 .hljs \u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236 */\n    font-size: 13px;\n    line-height: 1.6;\n    border-radius: 4px;\n    font-family: \"SFMono-Regular\", Consolas, Menlo, monospace;\n    overflow-x: auto;\n    white-space: pre;\n  min-width: max-content;\n    border: none;\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u6DF1\u7070\u8272 */\n#wemd pre code:not(.hljs) {\n    color: #37352F;\n    background: #F7F6F3;\n}\n\n/* \u8868\u683C - \u6570\u636E\u5E93\u98CE\u683C (Database) */\n#wemd table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 30px 0;\n    font-size: 14px;\n    border: 1px solid #E3E2E0;\n    border-radius: 0;\n}\n\n#wemd table tr th {\n    background: #F7F6F3;\n    color: #37352F;\n    font-weight: 600;\n    border: 1px solid #E3E2E0;\n    padding: 10px 12px;\n    text-align: left;\n}\n\n#wemd table tr td {\n    border: 1px solid #E3E2E0;\n    padding: 10px 12px;\n    color: #37352F;\n    background: #fff;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #37352F;\n    text-decoration: underline;\n}\n\n#wemd .footnotes-sep {\n    border-top: 1px solid #E3E2E0;\n    padding-top: 20px;\n    margin-top: 50px;\n    font-size: 12px;\n    color: #999;\n}\n\n#wemd .footnote-num {\n    font-weight: bold;\n    color: #37352F;\n    margin-right: 4px;\n}\n\n#wemd .footnote-item p {\n    color: #666;\n    font-size: 12px;\n    margin: 4px 0;\n}\n\n/* \u516C\u5F0F */\n#wemd .block-equation > svg {\n    max-width: 100% !important;\n}\n\n#wemd .inline-equation > svg {\n    max-width: 100%;\n    vertical-align: middle;\n}\n\n\n/* \u63D0\u793A\u5757 - \u77E5\u8BC6\u5E93\u98CE\u683C */\n#wemd .callout {\n    margin: 24px 0;\n    padding: 16px 16px 16px 20px;\n    border-radius: 4px;\n    border-left: 4px solid #37352F;\n}\n\n#wemd .callout-title {\n    font-weight: 600;\n    margin-bottom: 8px;\n    color: #37352F;\n    font-size: 15px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n    margin-right: 6px;\n}\n\n#wemd .callout-note { \n    background: #F1F1EF;\n    border-left-color: #37352F;\n}\n\n#wemd .callout-tip { \n    background: #FDF5F2;\n    border-left-color: #F2994A;\n}\n\n#wemd .callout-important { \n    background: #E7F3F8;\n    border-left-color: #2D9CDB;\n}\n\n#wemd .callout-warning { \n    background: #FFF4E5;\n    border-left-color: #FF9800;\n}\n\n#wemd .callout-caution { \n    background: #FFEBEE;\n    border-left-color: #F44336;\n}\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
